    if (!word) { var wj = row.querySelector(".word-jp"); word = wj ? wj.textContent.trim() : ""; }
    var rt = ruby ? ruby.querySelector("rt") : null;
    var reading = rt ? rt.textContent.trim() : "";
    if (!reading) reading = word;
    var w = kana(word), r = kana(reading || word);
    if (w.charAt(0) === "～") { w = "３" + w.slice(1); r = "さん" + r.replace(/^～/, ""); }
    var bnEl = row.querySelector(".word-bn");
